import{_ as r,c as a,o as i,ag as o}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Archival-research","description":"","frontmatter":{"title":"Archival-research"},"headers":[],"relativePath":"research/archival-research.md","filePath":"research/archival-research.md","lastUpdated":null}'),s={name:"research/archival-research.md"};function t(n,e,l,c,h,g){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="archival-research" tabindex="-1">Archival-research <a class="header-anchor" href="#archival-research" aria-label="Permalink to &quot;Archival-research&quot;">​</a></h1><h2 id="tools-and-methods-for-archival-research" tabindex="-1">Tools and Methods for Archival Research <a class="header-anchor" href="#tools-and-methods-for-archival-research" aria-label="Permalink to &quot;Tools and Methods for Archival Research&quot;">​</a></h2><p>Return to <a href="/research/">Section</a> See [Leveraging historical research methods enriches OSINT investigations. This guide outlines tools and archival resources, as well as methodological insights for OSINT practitioners.</p><p>The effectiveness of archival research in OSINT lies in your ability to creatively dig deeper, build personal collections, and critically assess the context and content of your findings.</p><h3 id="embracing-historical-methods-in-osint" tabindex="-1">Embracing Historical Methods in OSINT <a class="header-anchor" href="#embracing-historical-methods-in-osint" aria-label="Permalink to &quot;Embracing Historical Methods in OSINT&quot;">​</a></h3><ul><li><p><strong>Underutilized Archives</strong>: Explore lesser-known archives for unique finds.</p></li><li><p>&#39; <a href="/general/notes.html">https://researchworks.oclc.org/archivegrid/ Archive Grid (US)</a></p></li><li><p>&#39; <a href="https://archiveshub.jisc.ac.uk/" target="_blank" rel="noreferrer">Archives Hub (UK)</a></p></li><li><p><a href="https://www.worldcat.org/" target="_blank" rel="noreferrer">WorldCat</a></p></li><li><p><strong>Libraries as Resource Hubs</strong>: University and public libraries can be a goldmine for research.</p></li><li><p>&#39; <a href="https://www.loc.gov/" target="_blank" rel="noreferrer">Library of Congress</a></p></li><li><p>&#39; <a href="https://www.archives.gov/" target="_blank" rel="noreferrer">National Archives</a></p></li></ul><h3 id="building-personal-research-archives" tabindex="-1">Building Personal Research Archives <a class="header-anchor" href="#building-personal-research-archives" aria-label="Permalink to &quot;Building Personal Research Archives&quot;">​</a></h3><ul><li><strong>Digital Archiving</strong>: Creating personal archives is vital for storing and indexing sources. <ul><li><strong><a href="http://www.httrack.com" target="_blank" rel="noreferrer">HTTrack</a></strong>: Website copier for offline browsing.</li><li><strong>Hunchly</strong>: Tool for capturing online research sessions. **&#39; <strong><a href="/research/research-citations.html">Zotero</a></strong>: Reference manager for saving and organizing research materials.</li></ul></li></ul><h3 id="critical-analysis-of-sources" tabindex="-1">Critical Analysis of Sources <a class="header-anchor" href="#critical-analysis-of-sources" aria-label="Permalink to &quot;Critical Analysis of Sources&quot;">​</a></h3><ul><li><strong>Reading Against the Grain</strong>: Interpret sources critically, looking for what’s omitted and exploring different perspectives. <ul><li><strong>Lumen Database</strong>: Tracks copyright takedown requests.</li><li><strong>Multilingual Wikipedia</strong>: Check entries in other languages for different content.</li></ul></li></ul><ul><li><strong>Talk Pages</strong>: Provides context and debates behind Wikipedia content.</li></ul><h3 id="tools-for-archival-recovery" tabindex="-1">Tools for Archival Recovery <a class="header-anchor" href="#tools-for-archival-recovery" aria-label="Permalink to &quot;Tools for Archival Recovery&quot;">​</a></h3><ul><li><strong>Recovering Deleted Content</strong>: Tools and methods to uncover what’s been deliberately removed or lost. <ul><li><strong>Google Transparency Report</strong>: Shows removed content from search results.</li><li><strong>Wayback Machine</strong>: Access archived versions of web pages.</li></ul></li></ul><ul><li><strong>DocFetcher</strong>: Desktop search application for creating a searchable index.</li></ul><h3 id="contextualizing-and-managing-research" tabindex="-1">Contextualizing and Managing Research <a class="header-anchor" href="#contextualizing-and-managing-research" aria-label="Permalink to &quot;Contextualizing and Managing Research&quot;">​</a></h3><ul><li><strong>Contextual Understanding</strong>: Grasping the socio-cultural backdrop of the sources to comprehend their full implications. <ul><li><strong>Forensic OSINT</strong>: Investigate using digital forensic principles.</li><li>**OSINT Framework&#39;&#39;&#39;: Collection of OSINT tools and resources.</li><li><strong>Deleted Tweets</strong>: Services to find removed Twitter content.</li></ul></li></ul>',16)])])}const f=r(s,[["render",t]]);export{u as __pageData,f as default};
